    <span v-else class="mb-mk__texto" :style="estiloDelTexto">{{ rotulo }}</span>

    <!-- Las que llevan dibujo Y nombre. -->
    <span v-if="dibujo && conNombre" class="mb-mk__pie">{{ rotulo }}</span>
