  color: #fff;
}

/*
  LA CAJA DONDE ENTRA CUALQUIERA.

  Ancho y alto fijos, y adentro el dibujo se acomoda solo sin
  deformarse (es lo que hace un `viewBox` por omision). El escudo usa
  los 40 de alto y le sobra ancho; el nombre usa los 120 de ancho y le
  sobra alto. Ninguno se estira.
*/
.mb-mk__svg {
  width: 120px;
  height: 42px;
  display: block;
}

.mb-mk--con-dibujo .mb-mk__svg { filter: drop-shadow(0 2px 4px rgba(0, 0, 0, .35)); }

.mb-mk__texto { font-weight: 800; line-height: 1; }

.mb-mk__pie {
  font-weight: 800;
  font-size: 12px;
  letter-spacing: .26em;
  text-transform: uppercase;
  line-height: 1;
}

@include en-celular {
  .mb-mk__svg { width: 98px; height: 34px; }
  .mb-mk__pie { font-size: 11px; }
}
